import{_ as s,a as i,b as p,c as n,d as l}from"./chunks/20260630_180431_b2bd6d0ee660a850.CORLl9Tp.js";import{g as r,o as d,c as o,l as t,b as c,H as h,ak as g}from"./chunks/framework.RmyZtvw3.js";import"./chunks/theme.LbNrb-oy.js";const w=JSON.parse('{"title":"测试2","description":"腾讯 Agent Mail 的实测接入与使用体验，涵盖申请邮箱、安装 CLI、授权验证、Codex 等 Agent 发邮件流程，以及二次确认和自动化工作流场景。关键词：Agent Mail, AI 邮箱, Codex, Agent 工作流","frontmatter":{"title":"测试2","date":"2026-07-07T00:00:00.000Z","updated":"2026-07-01T00:00:00.000Z","lastUpdated":"2026-07-01T09:31:13.000Z","description":"腾讯 Agent Mail 的实测接入与使用体验，涵盖申请邮箱、安装 CLI、授权验证、Codex 等 Agent 发邮件流程，以及二次确认和自动化工作流场景。关键词：Agent Mail, AI 邮箱, Codex, Agent 工作流","tags":["Markdown","Skill"],"icon":"aiChat"},"headers":[],"relativePath":"test/test1 copy 2.md","filePath":"test/test1 copy 2.md","lastUpdated":1782898273000}'),u={name:"test/test1 copy 2.md"};function m(v,a,b,k,_,A){const e=s;return d(),o("div",null,[a[0]||(a[0]=t("h1",{id:"测试",tabindex:"-1"},[c("测试 "),t("a",{class:"header-anchor",href:"#测试","aria-label":'Permalink to "测试"'},"​")],-1)),h(e),a[1]||(a[1]=g('<p>腾讯 QQ 邮箱团队最近开始测试一个很有意思的新产品：<a href="https://agent.qq.com/" target="_blank" rel="noreferrer"><strong>Agent Mail</strong></a>。</p><p>它不是给人用的传统邮箱，而是给 <strong>AI Agent 用的专属邮箱</strong>。简单说，你可以给自己的 Agent 分配一个 <code>xxx@agent.qq.com</code> 邮箱地址，让它像一个真正的助理一样收邮件、读邮件、写邮件、发附件，甚至配合定时任务处理工作流。</p><p>官方文档里对它的定位很明确：Agent Mail 是 QQ 邮箱团队为 Agent 打造的专属邮箱服务，和个人邮箱隔离，原生适配 Agent，目标是让 Agent 能安全、高效地收发邮件。</p><h2 id="实际体验" tabindex="-1">实际体验 <a class="header-anchor" href="#实际体验" aria-label="Permalink to &quot;实际体验&quot;">​</a></h2><p>我实际体验下来，最直观的感受是：这不是“给邮箱套一层 AI 总结”，而是把邮箱能力开放给 Agent，让 <strong>Agent 真正拥有一个可操作的通信入口</strong>（高度相似把 Agent 接入微信或者钉钉、飞书等，只不过多了一层邮件的功能）。</p><p><img src="'+i+'" alt="实际体验"></p><p>目前官方文档显示，Agent Mail 已支持 WorkBuddy、QClaw、Marvis、OpenClaw、Claude Code、Kimi Work、豆包超能模式、Codex、Hermes、Cursor 等 Agent。我这次是在 Codex 里接入测试的，完整流程包括安装 CLI、安装 skill、OAuth 授权、验证邮箱地址，以及最后实际发送邮件。</p><p>这里我注册的邮箱地址是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>weizwz@agent.qq.com</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>如果你也想要一个好记的 Agent 邮箱 ID，现在应该就是比较适合去抢的时候。官方文档里提到，邮箱地址可以修改，但每个地址仅能修改一次，修改后旧地址会失效。</p><p>实际测试，<strong>每个人可以申请两个邮箱，ID 最少 6 位数，且目前没找到修改 ID 的入口</strong>，注销后也不能申请新的邮箱地址，只能恢复之前的地址。所以注册前，请确认好你想要的 ID。</p><h2 id="接入步骤" tabindex="-1">接入步骤 <a class="header-anchor" href="#接入步骤" aria-label="Permalink to &quot;接入步骤&quot;">​</a></h2><p>官方给出的接入方式很 Agent：你不需要自己记一堆命令，只要把官方提示词发给支持的 Agent，让 Agent 按文档操作即可。</p><p>我当时在 Codex 线程里发送的是这句话：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请阅读 https://agent.qq.com/doc/cli-setup.md 文档，按照步骤为我安装并配置 Agent Mail CLI。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><img src="'+p+'" alt="接入步骤"></p><p>从这次实测看，接入速度还是比较慢的（主要卡在沙箱网络限制），完整接入大概分四步。</p><p><strong>第一步，Agent 阅读官方安装文档，并检查本机环境。</strong></p><p>我这边的 Agent 先读取了 <code>https://agent.qq.com/doc/cli-setup.md</code>，确认流程是安装 <code>@tencent-qqmail/agently-cli</code>，再安装 Agent Mail 对应的 skill，然后进行 OAuth 登录，最后用 <code>agently-cli +me</code> 验证。</p><p><strong>第二步，安装 Agent Mail CLI。</strong></p><p>官方 CLI 安装命令是：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @tencent-qqmail/agently-cli</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>我的环境里第一次安装被沙箱网络限制拦了一下，放行后安装成功。安装完成后，CLI 版本显示为 <code>1.0.6</code>。</p><p><strong>第三步，安装 Agent Mail skill。</strong></p><p>官方文档里的命令是：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://agent.qq.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这一步的作用是让 Agent 知道怎么调用 Agent Mail，比如如何发邮件、读邮件、搜索邮件、下载附件，以及哪些操作必须二次确认。</p><p>我的实测里，skill 成功落到了 Codex 可用的位置：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.agents/skills/agently-mail</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>第四步，OAuth 授权。</strong></p><p>Agent 会运行：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agently-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>然后返回一个授权链接。打开链接后，用微信扫码完成授权。授权成功后，Agent 再运行：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agently-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +me</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>我这边最终看到的验证结果是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>邮箱地址 weizwz@agent.qq.com 已授权成功，可以用它来收发邮件了</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这里有一个小细节：在普通沙箱里读系统钥匙串时，曾出现过 <code>keychain not initialized</code>。后来用授权模式重新执行验证命令，就能正常读取凭据。也就是说，如果你在 Agent 环境里遇到类似钥匙串或凭据读取问题，不一定是授权失败，可能只是运行环境权限不够。</p><h2 id="开始使用" tabindex="-1">开始使用 <a class="header-anchor" href="#开始使用" aria-label="Permalink to &quot;开始使用&quot;">​</a></h2><p>接入完成以后，就不需要记 CLI 命令了。你可以直接用自然语言告诉 Agent 要做什么。</p><p>官方文档给的例子包括：</p><table tabindex="0"><thead><tr><th>场景</th><th>可以这样说</th></tr></thead><tbody><tr><td>发邮件</td><td>帮我给 <code>xxx@mail.com</code> 发一封邮件，内容是……</td></tr><tr><td>查看收件</td><td>看看我最近收到了哪些邮件</td></tr><tr><td>检索邮件</td><td>找一下上周关于项目进度的那封邮件</td></tr><tr><td>删除邮件</td><td>删除主题为 xxx 的邮件</td></tr><tr><td>回复邮件</td><td>回复刚才那封邮件，告诉对方我已收到</td></tr><tr><td>发送附件</td><td>发邮件给 xxx，并把这份文件作为附件</td></tr><tr><td>下载附件</td><td>把主题为 xxx 邮件的附件下载到本地</td></tr></tbody></table><p>我这次测试的是一个比较完整的任务：让 Agent 查西安本周天气，并通过 Agent Mail 发邮件。</p><p>我的第一句是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>发一封西安本周天气邮件</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><img src="'+n+`" alt="开始使用"></p><p>Agent 先去查询西安未来一周天气。因为天气属于实时信息，它先尝试了内置天气查询，又换到公开天气接口，最后拿到 2026-06-27 到 2026-07-03 的西安天气预报：整体高温，最高约 34-40°C，周日到周三有一定降水或雷阵雨概率，紫外线偏强。</p><p>然后 Agent 问我要收件人地址。我回复：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>发送给 weizwz.ai@gmail.com，签名是：你的好友 weizwz</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>接下来比较值得夸的一点是，Agent Mail 对写操作有明确的<strong>两阶段确认</strong>。</p><p>第一次调用发送命令时，它不会直接把邮件发出去，而是先生成确认摘要。我看到的摘要大概是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>发件人：weizwz@agent.qq.com</span></span>
<span class="line"><span>收件人：weizwz.ai@gmail.com</span></span>
<span class="line"><span>主题：西安本周天气预报</span></span>
<span class="line"><span>附件：无</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>然后 Agent 停下来等我确认。我回复：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>发送</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Agent 才执行第二阶段发送，并返回：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>已发送，邮件已进入发送队列。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这个流程让我比较放心。因为邮件是对外通信，发错对象、发错内容、误发附件都会很麻烦。Agent Mail 把发送、回复、转发、移到回收站这类写操作都设计成需要确认，避免 Agent 在一次对话里“自问自答”直接执行。</p><p>从体验上看，Agent Mail 最适合的不是单纯“帮我发一封邮件”，而是更自动化的工作流，比如：</p><ol><li>用 Agent Mail 订阅行业 newsletter，让 Agent 每天整理重点，再发到你的私人邮箱。</li><li>让 Agent 定时检索某个主题，把日报、周报通过 Agent Mail 发给你。</li><li>把发票邮件转发到 Agent Mail，让 Agent 提取附件或正文里的发票链接，再整理到表格。</li><li>把个人邮箱里需要 AI 处理的邮件自动转发到 Agent Mail，让 Agent 做分类、摘要、附件下载和重命名。</li><li>给某个项目单独配置一个 Agent Mail 地址，让外部系统、表单、监控告警都发到这里，再由 Agent 统一处理。</li></ol><p>这类场景以前也能用脚本拼出来，但门槛比较高。Agent Mail 的价值在于：邮箱地址、授权、CLI、Agent skill、确认机制都被串起来了，普通用户只要用自然语言描述需求就可以开始。</p><h2 id="其他问题" tabindex="-1">其他问题 <a class="header-anchor" href="#其他问题" aria-label="Permalink to &quot;其他问题&quot;">​</a></h2><p><strong>会用到我的私人 QQ 邮箱吗？</strong></p><p>不会。官方文档明确说，Agent 使用的是独立创建的专属地址，和个人邮箱完全隔离，互不影响。这一点很重要，因为 Agent Mail 更像是给 Agent 的工作邮箱，而不是把你的私人邮箱直接交给 Agent。</p><p><strong>在哪里管理 Agent 邮箱？</strong></p><p>访问：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://agent.qq.com</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>可以管理你的 Agent Mail 邮箱地址。</p><p><img src="`+l+'" alt="其他问题"></p><p><strong>邮箱地址能改吗？</strong></p><p>官方文档说可以改，且每个邮箱地址仅能修改一次，修改后旧地址会失效。但实测并没有找到修改入口，所以如果你想要一个短一点、好记一点、品牌化一点的 ID，建议注册后尽早想清楚。</p><p><strong>同一台电脑上的多个 Agent 能接不同地址吗？</strong></p><p>按照官方常见问题，目前同一台电脑设备上的多个 Agent 只能共同使用同一个邮箱地址。如果要使用不同地址，需要在不同电脑设备上使用。</p><p><strong>扫码登录失败怎么办？</strong></p><p>官方建议有两点：</p><ol><li>把 Agent 给出的授权链接原样复制到浏览器打开，不要改链接内容。</li><li>如果链接过期，就让 Agent 重新生成新的授权链接。</li></ol><p>你可以直接对 Agent 说：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请帮我生成新的 Agent Mail 的授权链接</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>Agent 会不会误发邮件？</strong></p><p>从我这次实测看，发送这类写操作不是直接执行，而是会先返回确认摘要，等用户明确回复“确认”或“发送”后才真正发送。这个二次确认机制是我觉得 Agent Mail 比较关键的安全设计。</p><p><strong>现在值不值得开通？</strong></p><p>如果你平时已经在用 Codex、Claude Code、Cursor、Kimi Work、豆包超能模式这类 Agent，我觉得值得。哪怕暂时只用来测试，也可以先把自己的 Agent 邮箱 ID 占住。</p><p>邮箱本身看起来只是一个地址，但一旦 Agent 能稳定收发邮件，它就不只是聊天窗口里的助手，而是可以进入真实工作流的协作者了。</p><h2 id="容器语法-rspress-风格" tabindex="-1">容器语法（Rspress 风格） <a class="header-anchor" href="#容器语法-rspress-风格" aria-label="Permalink to &quot;容器语法（Rspress 风格）&quot;">​</a></h2><p>八种类型，语法与 <a href="https://rspress.rs/zh/ui/components/callout" target="_blank" rel="noreferrer">Rspress 的 Callout</a> 一致： <code>:::tip</code>、<code>:::tip 自定义标题</code>、<code>:::tip{title=&quot;自定义标题&quot;}</code>，嵌套用更多的冒号（<code>::::</code>）。</p><div class="rp-callout rp-callout--note"><div class="rp-callout__title">Note</div><div class="rp-callout__content"><p><code>note</code>：默认标题就是类型名首字母大写，这里还带了行内 <code>code</code> 和<a href="#容器语法rspress-风格">链接</a>。</p></div></div><div class="rp-callout rp-callout--tip"><div class="rp-callout__title">Tip</div><div class="rp-callout__content"><p><code>tip</code>：提示。</p></div></div><div class="rp-callout rp-callout--tip"><div class="rp-callout__title"><strong>自定义</strong>标题</div><div class="rp-callout__content"><p>标题支持行内 markdown。</p></div></div><div class="rp-callout rp-callout--important"><div class="rp-callout__title">Important</div><div class="rp-callout__content"><p><code>important</code>：重要。</p></div></div><div class="rp-callout rp-callout--info"><div class="rp-callout__title">Info</div><div class="rp-callout__content"><p><code>info</code>：信息。</p></div></div><div class="rp-callout rp-callout--warning"><div class="rp-callout__title">Warning</div><div class="rp-callout__content"><p><code>warning</code>：警告。</p></div></div><div class="rp-callout rp-callout--danger"><div class="rp-callout__title">Danger</div><div class="rp-callout__content"><p><code>danger</code>：危险。</p></div></div><div class="rp-callout rp-callout--caution"><div class="rp-callout__title">Caution</div><div class="rp-callout__content"><p><code>caution</code>：注意。Rspress 里它和 <code>danger</code> 共用一套配色。</p></div></div><details class="rp-callout rp-callout--details"><summary class="rp-callout__title">展开查看</summary><div class="rp-callout__content"><p><code>details</code>：可折叠。</p></div></details><h3 id="prompt-卡片" tabindex="-1">Prompt 卡片 <a class="header-anchor" href="#prompt-卡片" aria-label="Permalink to &quot;Prompt 卡片&quot;">​</a></h3><div class="rp-prompt" style="--rp-prompt-accent:#6366F1;"><div class="rp-prompt__backdrop"></div><div class="rp-prompt__panel"><div class="rp-prompt__header"><div class="rp-prompt__meta"><span class="rp-prompt__eyebrow"><span class="rp-prompt__icon" title="Codex"><svg aria-hidden="true" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path d="M19.503 0H4.496A4.496 4.496 0 000 4.496v15.007A4.496 4.496 0 004.496 24h15.007A4.496 4.496 0 0024 19.503V4.496A4.496 4.496 0 0019.503 0z" fill="#fff"></path><path d="M9.064 3.344a4.578 4.578 0 012.285-.312c1 .115 1.891.54 2.673 1.275.01.01.024.017.037.021a.09.09 0 00.043 0 4.55 4.55 0 013.046.275l.047.022.116.057a4.581 4.581 0 012.188 2.399c.209.51.313 1.041.315 1.595a4.24 4.24 0 01-.134 1.223.123.123 0 00.03.115c.594.607.988 1.33 1.183 2.17.289 1.425-.007 2.71-.887 3.854l-.136.166a4.548 4.548 0 01-2.201 1.388.123.123 0 00-.081.076c-.191.551-.383 1.023-.74 1.494-.9 1.187-2.222 1.846-3.711 1.838-1.187-.006-2.239-.44-3.157-1.302a.107.107 0 00-.105-.024c-.388.125-.78.143-1.204.138a4.441 4.441 0 01-1.945-.466 4.544 4.544 0 01-1.61-1.335c-.152-.202-.303-.392-.414-.617a5.81 5.81 0 01-.37-.961 4.582 4.582 0 01-.014-2.298.124.124 0 00.006-.056.085.085 0 00-.027-.048 4.467 4.467 0 01-1.034-1.651 3.896 3.896 0 01-.251-1.192 5.189 5.189 0 01.141-1.6c.337-1.112.982-1.985 1.933-2.618.212-.141.413-.251.601-.33.215-.089.43-.164.646-.227a.098.098 0 00.065-.066 4.51 4.51 0 01.829-1.615 4.535 4.535 0 011.837-1.388zm3.482 10.565a.637.637 0 000 1.272h3.636a.637.637 0 100-1.272h-3.636zM8.462 9.23a.637.637 0 00-1.106.631l1.272 2.224-1.266 2.136a.636.636 0 101.095.649l1.454-2.455a.636.636 0 00.005-.64L8.462 9.23z" fill="#6366F1"></path></svg></span>For your Agent</span></div><div class="rp-prompt__header-row"><div class="rp-prompt__header-left"><div class="rp-prompt__title-with-icon"><div class="rp-prompt__title">一键创建 Rspress 项目</div></div><p class="rp-prompt__description">复制这段 Prompt 发送给你的 AI Agent，它会自动帮你搭建一个全新的 Rspress 站点。</p></div><div class="rp-prompt__header-actions"><button type="button" class="rp-prompt__action-copy" title="复制 Prompt"><svg class="rp-prompt__action-icon" xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 24 24"><path fill="currentColor" d="M20 8v12H8V8zm0-2H8a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8a2 2 0 0 0-2-2"></path><path fill="currentColor" d="M4 16H2V4a2 2 0 0 1 2-2h12v2H4Z"></path></svg><span>复制 Prompt</span></button><button type="button" class="rp-prompt__action-toggle" aria-controls="rp-prompt-content-1" aria-expanded="false" title="展开"><svg class="rp-prompt__action-toggle-icon" width="1em" height="1em" viewBox="0 0 32 32"><path fill="currentColor" d="M16 22 6 12l1.4-1.4 8.6 8.6 8.6-8.6L26 12z"></path></svg></button></div></div></div><div id="rp-prompt-content-1" class="rp-prompt__content rp-prompt__content--collapsed" aria-hidden="true"><div class="rp-prompt__content-inner"><div class="rp-prompt__content-body" style="white-space:pre-wrap;">按照官方快速开始指南 https://rspress.rs/guide/start/getting-started.md 创建一个 Rspress 项目。 1. 使用 `create rspress@latest` 初始化项目。 2. 安装依赖。 3. 启动开发服务器。 4. 确认页面正常渲染。</div></div></div></div></div><p><code>{custom}</code> 形态（对应 Rspress 的 <code>&lt;Prompt custom&gt;</code>）：只有眉标与外框，没有复制与展开按钮， 正文按 markdown 渲染。</p><div class="rp-prompt rp-prompt--custom" style="--rp-prompt-accent:#6366F1;"><div class="rp-prompt__backdrop"></div><div class="rp-prompt__panel"><div class="rp-prompt__header"><div class="rp-prompt__meta"><span class="rp-prompt__eyebrow"><span class="rp-prompt__icon" title="Codex"><svg aria-hidden="true" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path d="M19.503 0H4.496A4.496 4.496 0 000 4.496v15.007A4.496 4.496 0 004.496 24h15.007A4.496 4.496 0 0024 19.503V4.496A4.496 4.496 0 0019.503 0z" fill="#fff"></path><path d="M9.064 3.344a4.578 4.578 0 012.285-.312c1 .115 1.891.54 2.673 1.275.01.01.024.017.037.021a.09.09 0 00.043 0 4.55 4.55 0 013.046.275l.047.022.116.057a4.581 4.581 0 012.188 2.399c.209.51.313 1.041.315 1.595a4.24 4.24 0 01-.134 1.223.123.123 0 00.03.115c.594.607.988 1.33 1.183 2.17.289 1.425-.007 2.71-.887 3.854l-.136.166a4.548 4.548 0 01-2.201 1.388.123.123 0 00-.081.076c-.191.551-.383 1.023-.74 1.494-.9 1.187-2.222 1.846-3.711 1.838-1.187-.006-2.239-.44-3.157-1.302a.107.107 0 00-.105-.024c-.388.125-.78.143-1.204.138a4.441 4.441 0 01-1.945-.466 4.544 4.544 0 01-1.61-1.335c-.152-.202-.303-.392-.414-.617a5.81 5.81 0 01-.37-.961 4.582 4.582 0 01-.014-2.298.124.124 0 00.006-.056.085.085 0 00-.027-.048 4.467 4.467 0 01-1.034-1.651 3.896 3.896 0 01-.251-1.192 5.189 5.189 0 01.141-1.6c.337-1.112.982-1.985 1.933-2.618.212-.141.413-.251.601-.33.215-.089.43-.164.646-.227a.098.098 0 00.065-.066 4.51 4.51 0 01.829-1.615 4.535 4.535 0 011.837-1.388zm3.482 10.565a.637.637 0 000 1.272h3.636a.637.637 0 100-1.272h-3.636zM8.462 9.23a.637.637 0 00-1.106.631l1.272 2.224-1.266 2.136a.636.636 0 101.095.649l1.454-2.455a.636.636 0 00.005-.64L8.462 9.23z" fill="#6366F1"></path></svg></span>For your Agent</span></div></div><div class="rp-prompt__custom-content"><p><strong>hello</strong> world</p></div></div></div><h3 id="steps-分步说明" tabindex="-1">Steps 分步说明 <a class="header-anchor" href="#steps-分步说明" aria-label="Permalink to &quot;Steps 分步说明&quot;">​</a></h3><p>对应 Rspress 的 <code>&lt;Steps&gt;</code>：容器里的 <code>##</code>–<code>######</code> 直属标题各开启一步，标题下的内容 就是这一步的正文。</p><div class="rp-steps"><h3 id="第一步" tabindex="-1">第一步 <a class="header-anchor" href="#第一步" aria-label="Permalink to &quot;第一步&quot;">​</a></h3><p>第一步的内容。</p><h3 id="第二步" tabindex="-1">第二步 <a class="header-anchor" href="#第二步" aria-label="Permalink to &quot;第二步&quot;">​</a></h3><blockquote><p>第二步的内容。</p></blockquote><h3 id="第三步" tabindex="-1">第三步 <a class="header-anchor" href="#第三步" aria-label="Permalink to &quot;第三步&quot;">​</a></h3><ol><li>列表也可以。</li><li>行内 <code>code</code> 与<a href="#steps-分步说明">链接</a>都正常。</li></ol></div>',99))])}const q=r(u,[["render",m]]);export{w as __pageData,q as default};
